// Private storage of offer PDFs (ADR-0008). Services only see DocumentStore;
// the BETA server keeps files in a private directory (file-document-store.ts),
// the demo in the browser, production in the private Supabase bucket
// `offer-documents`. Keys are generated by the server, never taken from a
// request: "<organizationId>/<offerId>/<documentId>.pdf" or
// "staging/<uploadId>.pdf" for an upload not yet saved with its offer.

export interface DocumentStore {
  put(key: string, bytes: Uint8Array): Promise<void>;
  /** The bytes, or null when there is no such document. */
  get(key: string): Promise<Uint8Array | null>;
  move(from: string, to: string): Promise<void>;
  delete(key: string): Promise<void>;
}

const SEGMENT = '[A-Za-z0-9_-]{1,64}';
const KEY_PATTERN = new RegExp(`^(staging/${SEGMENT}|${SEGMENT}/${SEGMENT}/${SEGMENT})\\.pdf$`);

/** Refuses anything that is not a server-made key (no "..", no slashes of its own). */
export function assertDocumentKey(key: string): string {
  if (!KEY_PATTERN.test(key)) throw new Error('Invalid document key');
  return key;
}

export const stagingKey = (uploadId: string) => assertDocumentKey(`staging/${uploadId}.pdf`);
export const documentKey = (organizationId: string, offerId: string, documentId: string) =>
  assertDocumentKey(`${organizationId}/${offerId}/${documentId}.pdf`);

/** In memory (tests; an app created without storage). */
export function createMemoryDocumentStore(): DocumentStore & { size(): number } {
  const files = new Map<string, Uint8Array>();
  return {
    async put(key, bytes) {
      files.set(assertDocumentKey(key), bytes.slice());
    },
    async get(key) {
      return files.get(assertDocumentKey(key))?.slice() ?? null;
    },
    async move(from, to) {
      const bytes = files.get(assertDocumentKey(from));
      if (!bytes) throw new Error('Missing document');
      files.set(assertDocumentKey(to), bytes);
      files.delete(from);
    },
    async delete(key) {
      files.delete(assertDocumentKey(key));
    },
    size: () => files.size,
  };
}
